const defaultDataFile = path.join(root, 'data', 'books.json');
const css = await readFile(path.join(root, 'style.css'), 'utf8');

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
