function dateLabel(value) {
  return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).format(new Date(value));
}

function layout(title, content) {
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#f7f5ef"><title>${escapeHtml(title)} · Margins</title>
<link rel="stylesheet" href="/style.css"></head><body>
<div class="shell"><header class="topbar"><a class="brand" href="/" aria-label="Margins home"><span class="brand-mark">M<span>·</span></span><span>Margins</span></a><span class="topbar-note">A little space for your reading life</span></header>
${content}<footer class="footer"><span>Margins</span><span>One page at a time.</span></footer></div>
<script>document.querySelectorAll('[data-copy-link]').forEach(button => button.addEventListener('click', async () => { try { await navigator.clipboard.writeText(window.location.href); button.textContent = 'Link copied'; setTimeout(() => button.textContent = 'Copy link', 2000); } catch { button.textContent = 'Copy the URL above'; } }));</script>
</body></html>`;
}

function bookCard(book, number) {
  return `<article class="book-card"><span class="book-number">${String(number).padStart(2, '0')}</span><div class="book-info"><h3><a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a></h3><p>by ${escapeHtml(book.author)}</p>${book.notes ? `<p class="note-preview">${escapeHtml(book.notes)}</p>` : ''}</div><div class="book-actions">${book.status === 'reading' ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button class="text-button" type="submit">Mark finished <span aria-hidden="true">↗</span></button></form>` : `<span class="finished-label">Finished ${dateLabel(book.finishedAt ?? book.createdAt)}</span>`}</div></article>`;
}

