  return `<section class="shelf"><div class="section-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${heading}</h2></div><span class="count">${books.length} ${books.length === 1 ? 'book' : 'books'}</span></div>${books.length ? `<div class="book-list">${books.map((book, i) => bookCard(book, i + 1)).join('')}</div>` : `<div class="empty-shelf">${emptyText}</div>`}</section>`;
}

function home(books) {
  const reading = books.filter(book => book.status === 'reading').reverse();
  const finished = books.filter(book => book.status === 'finished').reverse();
  return layout('Your books', `<main><div class="hero"><div><span class="eyebrow">Your personal bookshelf</span><h1>Keep the books.<br><em>Keep the thoughts.</em></h1><p>A quiet place for what you’re reading, what you’ve finished, and the things you don’t want to forget.</p></div><a class="hero-link" href="#add-book">Add a book <span aria-hidden="true">↘</span></a></div>
