  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 30000) {
      const error = new Error('Form is too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

export function createAppServer({ dataFile = defaultDataFile } = {}) {
  let queue = Promise.resolve();

  async function readBooks() {
    try {
      const books = JSON.parse(await readFile(dataFile, 'utf8'));
      if (!Array.isArray(books)) throw new Error('Book data must be an array');
      return books;
    } catch (error) {
      if (error.code === 'ENOENT') return [];
      throw error;
    }
  }

  async function mutate(callback) {
    const operation = queue.then(async () => {
      const books = await readBooks();
      const result = callback(books);
      await mkdir(path.dirname(dataFile), { recursive: true });
      const temporaryFile = `${dataFile}.${randomUUID()}.tmp`;
      try {
        await writeFile(temporaryFile, JSON.stringify(books, null, 2) + '\n');
        await rename(temporaryFile, dataFile);
      } catch (error) {
        // A failed save must not leave a partial data file behind.
        const { rm } = await import('node:fs/promises');
        await rm(temporaryFile, { force: true });
        throw error;
      }
      return result;
    });
    queue = operation.catch(() => {});
    return operation;
  }

  return http.createServer(async (req, res) => {
    try {
      const pathname = new URL(req.url, 'http://localhost').pathname;
      if (req.method === 'GET' && pathname === '/style.css') {
        res.writeHead(200, { 'Content-Type': 'text/css; charset=utf-8' });
        res.end(css);
        return;
      }
      if (req.method === 'GET' && pathname === '/') {
        response(res, 200, home(await readBooks()));
        return;
      }
      if (req.method === 'POST' && pathname === '/books') {
        const fields = await formData(req);
        const title = (fields.get('title') ?? '').trim();
        const author = (fields.get('author') ?? '').trim();
        const notes = (fields.get('notes') ?? '').trim();
        if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
          response(res, 400, layout('Invalid book', '<main class="message"><h1>Check your book details</h1><p>A title and author are required. Please keep the title and author under 200 characters and notes under 10,000.</p><a href="/">Back to your shelf</a></main>'));
          return;
        }
        const book = { id: randomUUID(), title, author, notes, status: 'reading', createdAt: new Date().toISOString(), finishedAt: null };
        await mutate(books => books.push(book));
        redirect(res, `/books/${book.id}`);
        return;
      }
      const match = /^\/books\/([a-f0-9-]{36})(\/finish)?$/.exec(pathname);
      if (match && req.method === 'GET' && !match[2]) {
        const book = (await readBooks()).find(item => item.id === match[1]);
        if (book) { response(res, 200, detail(book)); return; }
      }
      if (match && req.method === 'POST' && match[2]) {
        const found = await mutate(books => {
          const book = books.find(item => item.id === match[1]);
          if (!book) return false;
          if (book.status !== 'finished') { book.status = 'finished'; book.finishedAt = new Date().toISOString(); }
          return true;
        });
        if (found) { redirect(res, `/books/${match[1]}`); return; }
      }
      response(res, 404, layout('Not found', '<main class="message"><span class="eyebrow">Lost your place?</span><h1>Page not found.</h1><p>That book isn’t on this shelf.</p><a href="/">Back to your shelf →</a></main>'));
    } catch (error) {
      console.error(error);
      response(res, error.status ?? 500, layout('Error', `<main class="message"><h1>Something went wrong.</h1><p>${error.status === 413 ? 'That form is too large.' : 'Please try again in a moment.'}</p><a href="/">Back to your shelf →</a></main>`));
    }
  });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT || 3000);
  createAppServer({ dataFile: process.env.BOOKS_FILE || defaultDataFile }).listen(port, () => console.log(`Margins is running at http://localhost:${port}`));
}
"}

