import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createAppServer } from './server.js';

async function listen(server) {
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  return `http://127.0.0.1:${server.address().port}`;
}

async function close(server) {
  await new Promise(resolve => server.close(resolve));
}

describe('book shelf', () => {
  it('adds books, shows details, finishes them, and keeps data after restart', async () => {
    const dir = await mkdtemp(path.join(tmpdir(), 'margins-'));
    const dataFile = path.join(dir, 'books.json');
    let server = createAppServer({ dataFile });
    try {
      let origin = await listen(server);
      let result = await fetch(origin);
      expect(result.status).toBe(200);
      expect(await result.text()).toContain('Currently reading');

      result = await fetch(`${origin}/books`, {
        method: 'POST', redirect: 'manual',
        body: new URLSearchParams({ title: '<A Good Book>', author: 'Someone & Co', notes: 'Remember this\nchapter.' })
      });
      expect(result.status).toBe(303);
      const bookPath = result.headers.get('location');
      expect(bookPath).toMatch(/^\/books\/[a-f0-9-]{36}$/);

      result = await fetch(origin + bookPath);
      const detail = await result.text();
      expect(detail).toContain('&lt;A Good Book&gt;');
      expect(detail).toContain('Someone &amp; Co');
      expect(detail).toContain('Remember this\nchapter.');
      expect(detail).not.toContain('<A Good Book>');
      expect((await (await fetch(origin)).text())).toContain('&lt;A Good Book&gt;');

      result = await fetch(origin + bookPath + '/finish', { method: 'POST', redirect: 'manual' });
      expect(result.status).toBe(303);
      const books = JSON.parse(await readFile(dataFile, 'utf8'));
      expect(books[0].status).toBe('finished');
      expect(books[0].finishedAt).toBeTruthy();

      await close(server);
      server = createAppServer({ dataFile });
      origin = await listen(server);
      const page = await (await fetch(origin + bookPath)).text();
      expect(page).toContain('Finished');
      expect(page).toContain('Remember this\nchapter.');
      expect((await (await fetch(origin)).text())).toContain('Finished');
      expect((await fetch(origin + '/books/00000000-0000-0000-0000-000000000000')).status).toBe(404);
    } finally {
      if (server.listening) await close(server);
      await rm(dir, { recursive: true, force: true });
    }
  });

  it('rejects incomplete books without creating data', async () => {
    const dir = await mkdtemp(path.join(tmpdir(), 'margins-'));
    const dataFile = path.join(dir, 'books.json');
    const server = createAppServer({ dataFile });
    try {
      const origin = await listen(server);
      const result = await fetch(`${origin}/books`, { method: 'POST', body: new URLSearchParams({ title: 'Only a title' }) });
      expect(result.status).toBe(400);
      expect((await (await fetch(origin)).text())).toContain('0 books');
    } finally {
      await close(server);
      await rm(dir, { recursive: true, force: true });
    }
  });
});
"}

